import string
import random


AVAILABLE_RANGE = string.ascii_uppercase + string.digits


def generate_random_string(length=30):
    """Method to generate random string with specific length."""
    return ''.join([generate_random_char() for each in range(length)])


def generate_random_char():
    """Method to generate random character."""
    return AVAILABLE_RANGE[random.randint(0, len(AVAILABLE_RANGE) - 1)]
